// OpenChurch UI strings — English and Spanish.
//
// Conventions (P4 — parish-native language):
//  - Liturgical Spanish follows parish usage: Bautismo, Confirmación,
//    Intenciones de Misa, el registro sacramental, padrinos.
//  - Certificate phrases avoid gendered participles ("recibió el
//    sacramento de…") so one string serves every name with reverence.
//  - {vars} are interpolated by t(); keep them identical across languages.
// Missing keys fall back to English, then to the key itself — a screen
// never breaks because a translation is missing.

import { NATIVE_AI_DISCLOSURE } from '../native/nativeAiDisclosure.js'

