    // ── Login / Narthex ──
    'login.h1': 'The parish office, kept well.',
    'login.p1': 'OpenChurch is quiet software for the daily work of a liturgical parish: planning worship, tending the liturgical calendar, knowing the members by name, recording the parish’s giving, and keeping the sacramental register — baptisms, confirmations, and marriages — the way a leather-bound book would keep them, only easier to search and impossible to lose.',
    'login.p2': 'It rests on a few convictions. That a sacramental record is a century-old document, not a database row. That the parish secretary’s Tuesday matters as much as Sunday morning. And that the register belongs to the parish, not to us — every record exports completely, any time.',
    'login.p3': 'Nothing here blinks, counts, or competes for your attention. Like a well-kept book, it waits until it is needed.',
    'login.traditions': 'Serving Catholic · Anglican · Lutheran parishes',
    'login.mobileBlurb': 'Quiet software for the work of a liturgical parish — worship, members, giving, the calendar, and the sacramental register, kept properly.',
    'login.welcome': 'Welcome back',
    'login.sub': "Sign in to your church's account.",
