    'mig.title': 'Migration Studio',
    'mig.subtitle': 'A careful move into the new parish office — reviewed before anything changes.',
    'mig.welcome1': 'Bringing your parish records into OpenChurch works like a careful move: clear boxes, labeled contents, and a chance to review everything before it is added. Nothing in this Studio changes your parish workspace until an administrator approves it.',
    'mig.canImport': 'What can come over now',
