    'mig.kind.gifts': 'Giving history',
    'mig.separately': 'What needs its own conversation',
    'mig.separatelyBody': 'The sacramental register, Mass intentions, clergy records, and paper or scanned books are never bulk-imported — they carry their own accountability and get their own governed process. Talk to OpenChurch about these.',
    'mig.promise': 'Every import here is reviewed by a person before anything is added: you will see what maps where, what needs attention, and what looks like a record you already have. An administrator gives the final approval, and a receipt records exactly what happened.',
    'mig.inventoryTitle': 'Before you start — what do you have?',
    'mig.inventoryIntro': 'A quiet checklist for gathering the boxes. Nothing here is scored or required.',
