    'help.miFulfillHowTitle': 'How do I mark an intention fulfilled (mark said)?',
    'help.miWeeklySheetTitle': 'What does the weekly sheet show, and which week does it open on?',
    'help.miWeeklySheetBody': 'The weekly sheet lists the Mass intentions for one week, Saturday through Friday, grouped by day, each with the Mass it is assigned to. It does not list Masses that have no intention. Monday through Saturday it opens on the coming weekend\u2019s week; on Sunday it opens on the weekend underway. Use Previous week, Next week or This week to move. An intention that has a date but no Mass yet still prints, marked \u201cUnassigned \u2014 needs a Mass\u201d; assign it a Mass in the book. Print it or save it as a PDF from your browser; OpenChurch does not email it.',
    // SP-253: weekday Mass Help. ES marked for native parish-language review.
    'help.miWeekdayMassTitle': 'How do I book an intention for a weekday Mass?',
    'help.miWeekdayMassBody': 'OpenChurch treats a weekday Mass the same as a Sunday Mass: it is a Schedule event of type Service on that date. If the Mass picker says there is no Mass on that date, choose "Add a Mass on this date" to open Schedule and add the Service, then return and assign the intention. The weekly sheet runs Saturday through Friday; on a weekday, "This week" means the coming weekend\u2019s week, so a Mass earlier this week is under Previous week. OpenChurch does not email the sheet.',
    'help.packetTitle': 'Where is the Sunday Packet?',
    'help.packetBody': 'The Sunday Packet is the printable sheet for one date: the order of worship, who is serving, that week\u2019s Mass intentions, and the bulletin announcements. People sometimes ask for it as the sacristy packet. It is not in the sidebar. Open it from the Dashboard, from Worship, or from Schedule, or search for sacristy or packet. Print it or save it as a PDF. OpenChurch does not email it.',
    'help.miFulfillHowBody': 'In the intention book, choose Edit intention, set Status to Fulfilled, and choose Save changes. A confirmation appears only after the book accepts the save. The intention must already be assigned to a Mass; if it is not, the save is refused, nothing is changed, and there is no confirmation. The weekly sheet shows the word "fulfilled" beside an intention with that status. Marking it fulfilled records that status in the book and does not change the offering. To mark several intentions said at once (bulk), choose the filter "Past scheduled — fulfilment not recorded" (it includes today\'s Masses once their start time has passed), tick the intentions that were said, and choose Review and mark said. Check the day each one was said, then confirm with the Mark … said button (it names how many); nothing is recorded until you confirm, and Undo puts them back.',
    'sup.title': 'Support',
    'sup.subtitle': 'Problem reports from your parish — what was reported, and where it stands.',
    'sup.subtitleVendor': 'Every parish’s reports, worst first. Triage, assign, resolve.',
    'sup.reportIntro': 'Describe what went wrong or what confused you — what you were doing, what you expected, what happened instead. Your current page and browser details are attached automatically.',
