    // ── Acceso / Nártex ──
    'login.h1': 'La oficina parroquial, bien llevada.',
    'login.p1': 'OpenChurch es un software sereno para el trabajo diario de una parroquia litúrgica: planear la liturgia, cuidar el calendario litúrgico, conocer a los miembros por su nombre, llevar cuenta de los donativos y custodiar el registro sacramental — bautismos, confirmaciones y matrimonios — como lo haría un libro encuadernado en piel, solo que más fácil de consultar e imposible de perder.',
    'login.p2': 'Descansa sobre unas pocas convicciones. Que un acta sacramental es un documento centenario, no una fila en una base de datos. Que el martes de la secretaria parroquial importa tanto como la mañana del domingo. Y que el registro pertenece a la parroquia, no a nosotros — cada acta se exporta completa, en cualquier momento.',
    'login.p3': 'Aquí nada parpadea, ni cuenta, ni compite por su atención. Como un libro bien llevado, espera hasta que se le necesita.',
    'login.traditions': 'Al servicio de parroquias católicas · anglicanas · luteranas',
    'login.mobileBlurb': 'Software sereno para el trabajo de una parroquia litúrgica — liturgia, miembros, donativos, el calendario y el registro sacramental, bien custodiados.',
    'login.welcome': 'Bienvenido de nuevo',
