    "cut.back": "Volver a Finanzas",
    "cut.guideTitle": "Día 1: traiga el balance de comprobación anterior",
    "cut.guide1": "En su sistema anterior, genere un balance de comprobación a una fecha (por ejemplo, el último cierre de mes).",
