    'mig.title': 'Estudio de migración',
    'mig.subtitle': 'Una mudanza cuidadosa a la nueva oficina parroquial — revisada antes de que algo cambie.',
    'mig.welcome1': 'Traer los registros de su parroquia a OpenChurch funciona como una mudanza cuidadosa: cajas claras, contenido etiquetado y la oportunidad de revisar todo antes de agregarlo. Nada en este Estudio cambia su espacio parroquial hasta que un administrador lo aprueba.',
    'mig.canImport': 'Qué puede traerse ahora',
    'mig.kind.members': 'Feligreses y miembros',
    'mig.kind.funds': 'Fondos de donaciones',
    'mig.kind.gifts': 'Historial de donaciones',
    'mig.separately': 'Qué necesita su propia conversación',
    'mig.separatelyBody': 'El registro sacramental, las intenciones de Misa, los registros del clero y los libros en papel o escaneados nunca se importan en masa — llevan su propia responsabilidad y tienen su propio proceso. Hable con OpenChurch sobre estos.',
    'mig.promise': 'Cada importación aquí la revisa una persona antes de agregar nada: verá qué va adónde, qué necesita atención y qué se parece a un registro que ya tiene. Un administrador da la aprobación final, y un recibo deja constancia exacta de lo que pasó.',
