    'help.tabGuide': 'Guía', 'help.tabFaq': 'Preguntas', 'help.tabRoles': 'Roles',
    'help.tabReport': 'Reportar un problema',
    'help.goodToKnow': 'Bueno saber',
    'help.nothingFound': 'No se encontró nada — pruebe el Asistente, o Reportar un problema si algo parece no funcionar.',
    'help.capability': 'Capacidad',
    'help.roleAdmin': 'Admin', 'help.roleStaff': 'Personal', 'help.roleViewer': 'Observador',
    'help.yes': 'Sí', 'help.no': 'No',
    'help.miFulfillHowTitle': '¿Cómo marco una intención como cumplida (marcar como dicha)?',
    'help.miWeeklySheetTitle': '¿Qué muestra la hoja semanal (weekly sheet) y en qué semana se abre?',
    'help.miWeeklySheetBody': 'La hoja semanal lista las intenciones de Misa de una semana, de sábado a viernes, agrupadas por día, cada una con la Misa asignada. No lista las Misas que no tienen intención. De lunes a sábado se abre en la semana del fin de semana próximo; el domingo, en el fin de semana en curso. Use Semana anterior, Semana siguiente o Esta semana para moverse. Una intención con fecha pero sin Misa se imprime igual, marcada \u201cSin asignar: necesita una Misa\u201d; asígnele una Misa en el libro. Imprímala o guárdela como PDF desde el navegador; OpenChurch no la envía por correo.',
    // SP-253 [ES: native review]
    'help.miWeekdayMassTitle': '¿Cómo registro una intención para una Misa de entre semana?',
    'help.miWeekdayMassBody': 'OpenChurch trata una Misa de entre semana igual que una del domingo: es un evento del Calendario de tipo Celebración en esa fecha. Si el selector de Misa dice que no hay Misa en esa fecha, elija «Agregar una Misa en esa fecha» para abrir el Calendario y agregar la Celebración; luego regrese y asigne la intención. La hoja semanal va del sábado al viernes; entre semana, «Esta semana» significa la semana del fin de semana próximo, así que una Misa de antes en esta semana está en Semana anterior. OpenChurch no envía la hoja por correo.',
    'help.packetTitle': '¿Dónde está el Paquete dominical (Sunday Packet)?',
    'help.packetBody': 'El Paquete dominical es la hoja imprimible de una fecha: el orden del culto, quién sirve, las intenciones de Misa de esa semana y los avisos del boletín. A veces se busca como el paquete de la sacristía. No está en la barra lateral. Ábralo desde el Panel, desde Liturgia o desde el Horario, o busque sacristía o paquete. Imprímalo o guárdelo como PDF. OpenChurch no lo envía por correo.',
    'help.miFulfillHowBody': 'En el libro de intenciones, elija Editar intención, ponga Estado en Cumplida y elija Guardar cambios. La confirmación aparece solo cuando el libro acepta el guardado. La intención debe estar ya asignada a una Misa; si no lo está, el guardado se rechaza, no cambia nada y no hay confirmación. La hoja semanal muestra la palabra "cumplida" junto a una intención con ese estado. Marcarla como cumplida registra ese estado en el libro y no cambia la ofrenda. Para marcar varias intenciones como dichas a la vez (en bloque), elija el filtro "Programadas con fecha pasada — cumplimiento no registrado" (incluye las Misas de hoy una vez pasada su hora de inicio), marque las intenciones que se dijeron y elija Revisar y marcar como dichas. Revise el día en que se dijo cada una y confirme; no se registra nada hasta que confirme, y Deshacer las devuelve como estaban.',
    'sup.title': 'Soporte',
    'sup.subtitle': 'Reportes de problemas de su parroquia — qué se reportó y en qué estado está.',
    'sup.subtitleVendor': 'Reportes de todas las parroquias, los más graves primero. Clasificar, asignar, resolver.',
    'sup.reportIntro': 'Describa qué salió mal o qué le confundió — qué estaba haciendo, qué esperaba y qué pasó en su lugar. Su página actual y los detalles del navegador se adjuntan automáticamente.',
    'sup.reportPh': 'Cuando intenté imprimir el manifiesto de sacristía…',
